        {'author': 'GhoshG.K.', 'title': 'GHOSHG.K.,2006, DISASTER MANAGEMENT, APH PUBLISHING CORPORATION.', 'publisher': '', 'edition_year': ' 2006', 'full_text': 'GhoshG.K.,2006, Disaster Management, APH Publishing Corporation.', 'section': 'TEXT'},
